contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // This test exercises Put then Collect for this contract instance.
    // Params:
    //  - putAmount: Ether to send to Put (must be supplied via this call's value)
    //  - unlockTime: value passed to Put
    //  - collectAmount: amount requested in Collect
    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "insufficient balance for Put");
        // Ensure this call provided the Ether intended for Put
        // Call Put with value putAmount
        c.Put{value: putAmount}(unlockTime);

        // Read holder state via public getter Acc(msg.sender) -> returns (unlockTime,balance)
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        // Record contract balance before Collect
        uint contractBalBefore = address(c).balance;

        bool collectReverted;
        // Try Collect; it may revert depending on conditions
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint contractBalAfter = address(c).balance;

        // General rule asserting correspondence between recorded balance change and Ether transfer when Collect succeeds,
        // and no change when Collect reverts. Also ensure unlockTime is never set below block.timestamp by Put.
        assert(
            (
                // If Collect reverted: balances and contract balance unchanged, and unlockTime unchanged
                collectReverted
                && beforeBalance == afterBalance
                && contractBalBefore == contractBalAfter
                && beforeUnlock == afterUnlock
            )
            ||
            (
                // If Collect succeeded: recorded balance decreased by collectAmount and contract balance decreased by collectAmount,
                // and unlockTime not decreased by Collect (should stay <=/>= as appropriate)
                !collectReverted
                && afterBalance + collectAmount == beforeBalance
                && contractBalAfter + collectAmount == contractBalBefore
                // Put should have set unlockTime at least to current block.timestamp at time of Put: afterUnlock >= beforeUnlock (Collect doesn't increase unlockTime),
                // but we can assert that afterUnlock >= beforeUnlock (Collect shouldn't reduce it)
                && afterUnlock >= beforeUnlock
            )
        );
    }

    // receive in case C sends Ether to this contract (not used but kept for completeness)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test: send putAmount to c.Put and check recorded and ether balances reflect at least that addition.
    // Params:
    //  - putAmount: Ether to send to Put (must be provided as msg.value to this transaction)
    //  - unlockTime: parameter passed to Put
    function run(uint putAmount, uint unlockTime) public payable {
        // require we actually provided the Ether intended for Put
        require(address(this).balance >= putAmount, "insufficient balance to fund Put");
        // Record contract observable state before Put
        uint contractBalBefore = address(c).balance;
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));

        // Call Put sending putAmount
        c.Put{value: putAmount}(unlockTime);

        // Read observed state after Put
        uint contractBalAfter = address(c).balance;
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

        // General invariant: the recorded balance for this holder increases by at least putAmount
        // and the contract's Ether balance increases by at least putAmount.
        // Also ensure Put set unlockTime to at least block.timestamp at time of the call: afterUnlock >= beforeUnlock and afterUnlock >= beforeUnlock (block.timestamp >= beforeUnlock might not hold if beforeUnlock was > block.timestamp),
        // but we assert that unlockTime did not decrease due to Put (afterUnlock >= beforeUnlock).
        assert(afterBalance >= beforeBalance && contractBalAfter >= contractBalBefore && afterBalance - beforeBalance >= putAmount - 0 && contractBalAfter - contractBalBefore >= putAmount - 0 && afterUnlock >= beforeUnlock);
    }

    // Allow receiving Ether (in case Collect sends funds)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test parameters:
    // putAmount: amount of wei to deposit via Put (sent as value)
    // unlockTime: unlock time passed to Put
    // collectAmt: amount requested to Collect
    function run(uint putAmount, uint unlockTime, uint collectAmt) public payable {
        // need funds to call Put
        require(address(this).balance >= putAmount, "insufficient balance to fund Put");

        // Ensure preconditions so Collect might succeed: put enough so that Acc.balance >= MinSum and >= collectAmt
        // We cannot read MinSum directly except via c.MinSum(), so read it.
        uint minSum = c.MinSum();

        // Ensure we deposit at least minSum and at least collectAmt
        uint deposit = putAmount;
        if (deposit < minSum) return; // if caller didn't provide enough, don't proceed (keeps assert reachable but only for valid inputs)
        if (deposit < collectAmt) return; // similarly require deposit >= collectAmt

        // Record observables before
        uint contractBalBefore = address(c).balance;
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));

        // Call Put to deposit
        c.Put{value: deposit}(unlockTime);

        // After Put, set time condition: we can only Collect if block.timestamp > acc.unlockTime.
        // We cannot change block.timestamp; however, Put sets unlockTime = max(_unlockTime, block.timestamp).
        // To allow Collect to succeed, require that provided unlockTime < block.timestamp so Put will set unlockTime = block.timestamp, and then Collect still needs block.timestamp > acc.unlockTime which will be false in same tx.
        // Therefore, Collect cannot succeed in same transaction unless _unlockTime < block.timestamp and some time passes; but checker runs single tx.
        // To create a successful Collect in same transaction, exploit that fallback Put with _unlockTime set to 0 with prior acc.unlockTime < block.timestamp could work. Instead, we reason about the general property conditional on Collect succeeding: perform Collect and observe whether it reverted.

        // Read state just before Collect
        (uint midUnlock, uint midBalance) = c.Acc(address(this));
        uint contractBalMid = address(c).balance;

        // Attempt Collect and capture revert
        bool reverted = false;
        // Collect is payable in signature but does not require value; call without value
        try c.Collect{value: 0}(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint contractBalAfter = address(c).balance;

        // If Collect did not revert, then the contract must have transferred collectAmt to this contract (msg.sender = this test contract)
        // and decreased the recorded holder balance by exactly collectAmt.
        // Formally assert: if not reverted then midBalance >= collectAmt and afterBalance == midBalance - collectAmt and contractBalAfter + collectAmt == contractBalMid
        // Use addition to avoid underflow in assert expression.
        assert(reverted || (midBalance >= collectAmt && afterBalance + collectAmt == midBalance && contractBalAfter + collectAmt == contractBalMid));
    }

    // Allow receiving Ether from C. Collect uses call to msg.sender so this contract must accept Ether.
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params:
    // putAmount: wei to send to Put
    // unlockTime: parameter to Put
    // collectAmt: amount to request in Collect
    function run(uint putAmount, uint unlockTime, uint collectAmt) public payable {
        // need funds to call Put
        require(address(this).balance >= putAmount, "insufficient balance to fund Put");

        // Read MinSum to ensure deposit is meaningful; if caller didn't provide enough to satisfy MinSum, we still proceed
        uint minSum = c.MinSum();

        // Record observables before any call
        uint contractBalBefore = address(c).balance;
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));

        // Make the deposit via Put (may change Acc and contract balance)
        c.Put{value: putAmount}(unlockTime);

        // Read state after Put and before Collect
        (uint midUnlock, uint midBalance) = c.Acc(address(this));
        uint contractBalMid = address(c).balance;

        // Attempt Collect and capture whether it reverted
        bool reverted;
        try c.Collect{value: 0}(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read state after Collect
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint contractBalAfter = address(c).balance;

        // General property:
        // If Collect succeeded then midBalance >= collectAmt and afterBalance == midBalance - collectAmt
        // and contractBalAfter == contractBalMid - collectAmt.
        // If Collect reverted then balances and contract balance remain as before the Collect attempt.
        // Use additions to avoid underflow in the assert expression.
        assert(
            (!reverted && midBalance >= collectAmt && afterBalance + collectAmt == midBalance && contractBalAfter + collectAmt == contractBalMid)
            || (reverted && afterBalance == midBalance && contractBalAfter == contractBalMid)
        );
    }

    // Accept Ether sent by C during Collect
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params:
    // putAmount: wei to send to Put
    // unlockTime: parameter to Put
    function run(uint putAmount, uint unlockTime) public payable {
        // ensure this test contract has enough balance to send putAmount
        require(address(this).balance >= putAmount);

        // Observables before Put
        uint contractBalBefore = address(c).balance;
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));

        // Perform Put sending putAmount wei
        c.Put{value: putAmount}(unlockTime);

        // Observables after Put
        uint contractBalAfter = address(c).balance;
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

        // General property:
        // 1) The contract's Ether balance increases by exactly putAmount.
        // 2) The recorded balance for this caller does not decrease (afterBalance >= beforeBalance)
        //    and increases by at most the sent amount plus any previous value (we assert at least that it increased by >=0 and that the delta is <= putAmount + ???).
        // Simpler and robust rule: afterBalance >= beforeBalance and contractBalAfter == contractBalBefore + putAmount
        assert(afterBalance >= beforeBalance && contractBalAfter == contractBalBefore + putAmount);
    }

    receive() external payable {}
}

