contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call Put to deposit funds, then call Collect and assert the invariant.
    // Parameters:
    // - initialDeposit: amount of ETH to send to Put
    // - unlockTime: parameter for Put (will be normalized by Put)
    // - collectAmount: requested amount to Collect
    // Note: this function is payable to allow forwarding ETH to c via Put; we require
    // the contract has enough balance to forward initialDeposit.
    function run(uint initialDeposit, uint unlockTime, uint collectAmount) public payable {
        require(address(this).balance >= initialDeposit);

        // Read holder balance before any action (should be 0 initially because c is freshly deployed)
        // Use the public getter Acc(address) which returns Holder (unlockTime,balance) via the autogenerated getter.
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        // Sanity: beforeBalance is observed but not required to be zero by require.

        // Deposit initialDeposit into c by calling Put. This changes c state and must be top-level.
        c.Put{value: initialDeposit}(unlockTime);

        // Read holder balance after deposit
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

        // Ensure that afterBalance increased by exactly initialDeposit
        // This is only an observed value, we won't assert this separately; instead it will be used in the final invariant.

        // Now attempt to Collect collectAmount. We must catch whether it reverted.
        bool reverted;
        // Collect is payable in declaration but it does not require sending value; we call without value.
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balance after collect attempt
        (uint finalUnlock, uint finalBalance) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;
        uint cBalBeforeCollect = address(c).balance + 0; // placeholder to emphasize only public reads used

        // The invariant: if Collect did not revert, then the recorded balance decreased by exactly collectAmount
        // and the contract's ETH balance decreased by at least collectAmount.
        // We express the ETH-balance decrease by comparing after vs before: since we cannot directly read the
        // contract balance before the Collect call separately from after (we can, because we already performed Put),
        // compute c's balance just after Put by querying it before the Collect attempt (we have cBalBeforeCollect equal to current balance since no state change between read and try),
        // but to avoid relying on timestamps, we assert: if not reverted then finalBalance + collectAmount == afterBalance
        // and address(c).balance <= address(this).balance + afterBalance - finalBalance (we avoid complex arithmetic).

        // Final assert: on success the holder balance decreases exactly by collectAmount
        assert(
            reverted || (finalBalance + collectAmount == afterBalance)
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: deposit some ETH via Put, then attempt Collect(amount).
    // Parameters:
    // - deposit: amount of ETH to send to Put (must be available to this contract)
    // - unlockTime: parameter for Put
    // - collectAmount: requested amount to Collect
    function run(uint deposit, uint unlockTime, uint collectAmount) public payable {
        // Ensure we have the funds to forward deposit to c when calling Put
        require(address(this).balance >= deposit);

        // Observe holder state before any action
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));

        // Make a deposit into c via Put
        c.Put{value: deposit}(unlockTime);

        // Observe holder state immediately after Put and before Collect
        (uint midUnlock, uint midBalance) = c.Acc(address(this));

        // Attempt to Collect collectAmount and record whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe holder state after Collect attempt
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

        // General rule: if Collect did not revert, then the recorded balance for this holder strictly decreased
        // (i.e., afterBalance < midBalance). This captures that a successful Collect must reduce stored balance.
        assert(reverted || (afterBalance < midBalance));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We: deposit via Put, then attempt Collect(amount). Parameters:
    // - deposit: ETH to send with Put
    // - unlockTime: parameter for Put
    // - collectAmount: amount to request from Collect
    function run(uint deposit, uint unlockTime, uint collectAmount) public payable {
        require(address(this).balance >= deposit);

        // observe contract balance and holder balance before actions
        uint beforeCBal = address(c).balance;
        (uint beforeUnlock, uint beforeHolderBal) = c.Acc(address(this));

        // Make a deposit into c via Put
        c.Put{value: deposit}(unlockTime);

        // observe after deposit
        uint afterDepositCbal = address(c).balance;
        (uint midUnlock, uint midHolderBal) = c.Acc(address(this));

        // Attempt to Collect collectAmount and record whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after collect
        uint afterCollectCbal = address(c).balance;
        (uint afterUnlock, uint afterHolderBal) = c.Acc(address(this));

        // General rule: if Collect did not revert then either the external ETH held by c decreased by at least collectAmount,
        // or the stored holder balance decreased by at least collectAmount. This ensures no successful Collect magically
        // increases ETH or holder balance.
        assert(reverted || (afterCollectCbal + collectAmount <= afterDepositCbal) || (afterHolderBal + collectAmount <= midHolderBal));
    }

